PRAGMA foreign_keys = ON;
CREATE TABLE portfolio_scope(id TEXT PRIMARY KEY CHECK(id='scope'), value TEXT NOT NULL UNIQUE);
CREATE TRIGGER portfolio_scope_no_update BEFORE UPDATE ON portfolio_scope BEGIN SELECT RAISE(ABORT,'scope immutable'); END;
CREATE TRIGGER portfolio_scope_no_delete BEFORE DELETE ON portfolio_scope BEGIN SELECT RAISE(ABORT,'scope immutable'); END;
CREATE TABLE companies(id TEXT PRIMARY KEY, name TEXT NOT NULL, request_id TEXT UNIQUE, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE company_aliases(id TEXT PRIMARY KEY REFERENCES companies(id), company_id TEXT NOT NULL REFERENCES companies(id), name TEXT NOT NULL, request_id TEXT NOT NULL UNIQUE, CHECK(id!=company_id));
CREATE TRIGGER alias_guard BEFORE INSERT ON company_aliases BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM company_aliases WHERE id=NEW.company_id OR company_id=NEW.id) THEN RAISE(ABORT,'link must use a root company') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM candidates a JOIN candidates b ON a.offer=b.offer AND a.motion=b.motion WHERE a.company_id=NEW.id AND (b.company_id=NEW.company_id OR b.company_id IN (SELECT id FROM company_aliases WHERE company_id=NEW.company_id))) THEN RAISE(ABORT,'duplicate candidate after link') END;
END;
CREATE TRIGGER aliases_no_update BEFORE UPDATE ON company_aliases BEGIN SELECT RAISE(ABORT,'append only'); END;
CREATE TRIGGER aliases_no_delete BEFORE DELETE ON company_aliases BEGIN SELECT RAISE(ABORT,'append only'); END;
CREATE TABLE candidates(id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), registry_id TEXT UNIQUE, offer TEXT NOT NULL, motion TEXT NOT NULL, registry_status TEXT NOT NULL CHECK(registry_status IN ('active','hold','future','excluded')), contact_allowed TEXT NOT NULL DEFAULT 'unknown' CHECK(contact_allowed IN ('yes','no','unknown')), next_action TEXT, next_date TEXT, request_id TEXT UNIQUE, version INTEGER NOT NULL DEFAULT 1, UNIQUE(company_id,offer,motion));
CREATE TRIGGER candidate_linked_unique BEFORE INSERT ON candidates WHEN EXISTS(SELECT 1 FROM candidates c WHERE c.offer=NEW.offer AND c.motion=NEW.motion AND COALESCE((SELECT company_id FROM company_aliases WHERE id=c.company_id),c.company_id)=COALESCE((SELECT company_id FROM company_aliases WHERE id=NEW.company_id),NEW.company_id)) BEGIN SELECT RAISE(ABORT,'duplicate linked candidate'); END;
CREATE TABLE limits(id TEXT PRIMARY KEY, offer TEXT NOT NULL, start_date TEXT NOT NULL, end_date TEXT NOT NULL, max_contacts INTEGER NOT NULL CHECK(max_contacts>=0), CHECK(start_date<=end_date));
CREATE TRIGGER limit_no_overlap BEFORE INSERT ON limits WHEN EXISTS(SELECT 1 FROM limits WHERE offer=NEW.offer AND start_date<=NEW.end_date AND end_date>=NEW.start_date) BEGIN SELECT RAISE(ABORT,'overlapping limit'); END;
CREATE TABLE events(id TEXT PRIMARY KEY, candidate_id TEXT NOT NULL REFERENCES candidates(id), kind TEXT NOT NULL CHECK(kind IN ('sent','form_accepted','automatic_reply','human_reply','unknown','refused','skipped','meeting','introduced','note')), occurred_on TEXT NOT NULL, evidence TEXT NOT NULL, note TEXT NOT NULL, request_id TEXT NOT NULL UNIQUE);
CREATE TRIGGER event_contact_guard BEFORE INSERT ON events WHEN NEW.kind IN ('sent','form_accepted','unknown') BEGIN
  SELECT CASE WHEN (SELECT contact_allowed FROM candidates WHERE id=NEW.candidate_id)!='yes' THEN RAISE(ABORT,'contact permission not confirmed') END;
  SELECT CASE WHEN (SELECT registry_status FROM candidates WHERE id=NEW.candidate_id)!='active' THEN RAISE(ABORT,'candidate not active') END;
  SELECT CASE WHEN EXISTS(SELECT 1 FROM events e JOIN candidates c ON c.id=e.candidate_id WHERE COALESCE((SELECT company_id FROM company_aliases WHERE id=c.company_id),c.company_id)=(SELECT COALESCE((SELECT company_id FROM company_aliases WHERE id=cc.company_id),cc.company_id) FROM candidates cc WHERE cc.id=NEW.candidate_id) AND e.kind='refused') THEN RAISE(ABORT,'company refused') END;
  SELECT CASE WHEN EXISTS(SELECT 1 FROM events WHERE candidate_id=NEW.candidate_id AND kind IN ('sent','form_accepted','unknown','skipped')) THEN RAISE(ABORT,'prior contact or hold') END;
  SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM limits p JOIN candidates c ON c.offer=p.offer WHERE c.id=NEW.candidate_id AND NEW.occurred_on BETWEEN p.start_date AND p.end_date) THEN RAISE(ABORT,'period not configured') END;
  SELECT CASE WHEN EXISTS(SELECT 1 FROM limits p JOIN candidates c ON c.offer=p.offer WHERE c.id=NEW.candidate_id AND NEW.occurred_on BETWEEN p.start_date AND p.end_date AND (SELECT COUNT(*) FROM events e JOIN candidates cc ON cc.id=e.candidate_id WHERE cc.offer=p.offer AND e.kind IN ('sent','form_accepted','unknown') AND e.occurred_on BETWEEN p.start_date AND p.end_date)>=p.max_contacts) THEN RAISE(ABORT,'period limit reached') END;
END;
CREATE TRIGGER events_no_update BEFORE UPDATE ON events BEGIN SELECT RAISE(ABORT,'append only'); END;
CREATE TRIGGER events_no_delete BEFORE DELETE ON events BEGIN SELECT RAISE(ABORT,'append only'); END;
CREATE TABLE contracts(id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), offer TEXT NOT NULL, dataset TEXT NOT NULL CHECK(dataset IN ('actual','demo')), currency TEXT NOT NULL, amount_minor INTEGER NOT NULL CHECK(amount_minor>0), cadence TEXT NOT NULL CHECK(cadence IN ('monthly','annual')), paid_from TEXT NOT NULL, paid_until TEXT, pause_from TEXT, pause_until TEXT, source_ref TEXT NOT NULL, source_url TEXT NOT NULL, recorded_on TEXT NOT NULL, confirmation TEXT NOT NULL CHECK(confirmation IN ('confirmed','unconfirmed')), supersedes TEXT REFERENCES contracts(id), request_id TEXT NOT NULL UNIQUE, UNIQUE(dataset,source_ref), UNIQUE(supersedes));
CREATE TABLE amounts(id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), offer TEXT NOT NULL, dataset TEXT NOT NULL CHECK(dataset IN ('actual','demo')), currency TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('revenue','payment','revenue_refund','payment_refund','revenue_cancel','payment_cancel','forecast')), amount_minor INTEGER NOT NULL CHECK(amount_minor>=0), occurred_on TEXT NOT NULL, period_start TEXT NOT NULL, period_end TEXT NOT NULL, source_ref TEXT NOT NULL, source_url TEXT NOT NULL, recorded_on TEXT NOT NULL, confirmation TEXT NOT NULL CHECK(confirmation IN ('confirmed','unconfirmed')), request_id TEXT NOT NULL UNIQUE, UNIQUE(dataset,source_ref), CHECK(period_start<=period_end));
CREATE TRIGGER contracts_no_update BEFORE UPDATE ON contracts BEGIN SELECT RAISE(ABORT,'append only'); END;
CREATE TRIGGER contracts_no_delete BEFORE DELETE ON contracts BEGIN SELECT RAISE(ABORT,'append only'); END;
CREATE TRIGGER amounts_no_update BEFORE UPDATE ON amounts BEGIN SELECT RAISE(ABORT,'append only'); END;
CREATE TRIGGER amounts_no_delete BEFORE DELETE ON amounts BEGIN SELECT RAISE(ABORT,'append only'); END;
CREATE TABLE action_changes(request_id TEXT PRIMARY KEY, candidate_id TEXT NOT NULL REFERENCES candidates(id), action TEXT, due_on TEXT, expected_version INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE action_results(request_id TEXT PRIMARY KEY REFERENCES action_changes(request_id), candidate_json TEXT NOT NULL);
CREATE TRIGGER action_change_version BEFORE INSERT ON action_changes WHEN NOT EXISTS(SELECT 1 FROM candidates WHERE id=NEW.candidate_id AND version=NEW.expected_version) BEGIN SELECT RAISE(ABORT,'stale or missing candidate'); END;
CREATE TRIGGER action_change_apply AFTER INSERT ON action_changes BEGIN UPDATE candidates SET next_action=NEW.action,next_date=NEW.due_on,version=version+1 WHERE id=NEW.candidate_id; INSERT INTO action_results(request_id,candidate_json) SELECT NEW.request_id,json_object('id',id,'company_id',company_id,'registry_id',registry_id,'offer',offer,'motion',motion,'registry_status',registry_status,'contact_allowed',contact_allowed,'next_action',next_action,'next_date',next_date,'version',version) FROM candidates WHERE id=NEW.candidate_id; END;
CREATE TRIGGER action_changes_no_update BEFORE UPDATE ON action_changes BEGIN SELECT RAISE(ABORT,'append only'); END;
CREATE TRIGGER action_changes_no_delete BEFORE DELETE ON action_changes BEGIN SELECT RAISE(ABORT,'append only'); END;
CREATE TRIGGER contract_revision_guard BEFORE INSERT ON contracts WHEN NEW.supersedes IS NOT NULL BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM contracts c WHERE c.id=NEW.supersedes AND c.company_id=NEW.company_id AND c.offer=NEW.offer AND c.dataset=NEW.dataset) THEN RAISE(ABORT,'invalid contract revision') END;
END;
CREATE TABLE local_pending_actions(id INTEGER PRIMARY KEY AUTOINCREMENT, scope TEXT NOT NULL, payload TEXT NOT NULL);
CREATE TABLE permission_changes(request_id TEXT PRIMARY KEY, candidate_id TEXT NOT NULL REFERENCES candidates(id), allowed TEXT NOT NULL CHECK(allowed IN ('yes','no','unknown')), evidence TEXT NOT NULL, expected_version INTEGER NOT NULL);
CREATE TRIGGER permission_change_version BEFORE INSERT ON permission_changes WHEN NOT EXISTS(SELECT 1 FROM candidates WHERE id=NEW.candidate_id AND version=NEW.expected_version) BEGIN SELECT RAISE(ABORT,'stale or missing candidate'); END;
CREATE TRIGGER permission_change_apply AFTER INSERT ON permission_changes BEGIN UPDATE candidates SET contact_allowed=NEW.allowed,version=version+1 WHERE id=NEW.candidate_id; END;
CREATE TRIGGER permission_changes_no_update BEFORE UPDATE ON permission_changes BEGIN SELECT RAISE(ABORT,'append only'); END;
CREATE TRIGGER permission_changes_no_delete BEFORE DELETE ON permission_changes BEGIN SELECT RAISE(ABORT,'append only'); END;
CREATE TRIGGER contract_candidate_guard BEFORE INSERT ON contracts WHEN NOT EXISTS(SELECT 1 FROM candidates c WHERE c.company_id=NEW.company_id AND c.offer=NEW.offer) BEGIN SELECT RAISE(ABORT,'company offer is not registered'); END;
CREATE TRIGGER amount_candidate_guard BEFORE INSERT ON amounts WHEN NOT EXISTS(SELECT 1 FROM candidates c WHERE c.company_id=NEW.company_id AND c.offer=NEW.offer) BEGIN SELECT RAISE(ABORT,'company offer is not registered'); END;
